@Transactional(readOnly = true)
public void streamLargeCsvExport(HttpServletResponse response) throws IOException {
    response.setContentType("text/csv");
    response.setHeader("Content-Disposition", "attachment; filename=export.csv");

    try (PrintWriter writer = response.getWriter();
         Stream<UserEntity> userStream = userRepository.streamAllActiveUsers()) {

        writer.println("id,username,email");

        userStream.forEach(user -> {
            writer.print(user.getId());
            writer.print(',');
            writer.print(user.getUsername());
            writer.print(',');
            writer.println(user.getEmail());

            // Optional: flush periodically for long streams
        });
        writer.flush();
    }
}
